package ingest

import "testing"

func TestGSRWitness(t *testing.T) {
	// "SmartPM" contains "tpm" as a substring, which causes a false positive
	// exclusion if the filter does not require word boundaries. It should survive
	// because "product manager" is an inclusion phrase and "tpm" is not a standalone word.
	got := PassesTitleFilter("SmartPM Product Manager")
	if got != true {
		t.Fatalf("PassesTitleFilter(\"SmartPM Product Manager\") = %v, want %v", got, true)
	}
}

