package store

import (
	"context"
	"testing"
)

type gsrWitnessReader struct {
	reads int
}

func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.reads++
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &gsrWitnessReader{}
	_, err := Fetch(ctx, r, "key")

	if r.reads != 0 {
		t.Fatalf("reads = %v, want 0", r.reads)
	}
	if err != context.Canceled {
		t.Fatalf("err = %v, want %v", err, context.Canceled)
	}
}

