package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	writes int
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	return []byte(`{}`), "etag1", nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Pre-cancel to test early abort behavior

	fs := &gsrWitnessFakeStorage{}
	store := Store{
		Storage: fs,
	}

	_, _ = store.Mutate(ctx, "http://profile", func(c Contact) Contact { return c })

	// If the retry loop respects ctx.Done(), it should abort without exhausting maxWriteRetries.
	if fs.writes >= maxWriteRetries {
		t.Fatalf("Mutate() write attempts = %d, want < %d (should abort early on cancelled context)", fs.writes, maxWriteRetries)
	}
}

package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessStorage struct {
	storage.Client
	writes int
}

func (m *gsrWitnessStorage) ReadFile(ctx context.Context, bucket string, key string) ([]byte, string, error) {
	// Return valid empty JSON so unmarshaling succeeds.
	return []byte(`{}`), "etag", nil
}

func (m *gsrWitnessStorage) WriteFile(ctx context.Context, bucket string, key string, data []byte, ifMatch string) error {
	m.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	m := &gsrWitnessStorage{}
	s := &Store{
		Storage: m,
		Bucket:  "test-bucket",
	}

	// Cancel the context immediately. If Mutate correctly selects on ctx.Done()
	// instead of just time.Sleep(), it should abort the loop without reaching
	// maxWriteRetries.
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	_, _ = s.Mutate(ctx, "test-profile", func(c Contact) Contact {
		return c
	})

	if m.writes >= maxWriteRetries {
		t.Fatalf("Store.Mutate(cancelled_ctx) made %d WriteFile calls, want < %d (should abort early)", m.writes, maxWriteRetries)
	}
}

