import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessMockStorage struct {
	storage.Client
}

func (m gsrWitnessMockStorage) ReadFile(ctx context.Context, bucket string, key string) ([]byte, string, error) {
	return []byte(`{}`), "etag1", nil
}

func (m gsrWitnessMockStorage) WriteFile(ctx context.Context, bucket string, key string, data []byte, ifMatch string) error {
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	s := Store{
		Storage: gsrWitnessMockStorage{},
		Bucket:  "test-bucket",
	}

	_, err := s.Mutate(ctx, "https://example.com/in/test", func(c Contact) Contact {
		return c
	})

	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() with cancelled context = %v, want error wrapping context.Canceled", err)
	}
}
